`timescale 1ns/1ps

module uart_tx #(
    parameter CLKS_PER_BIT = 16
) (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       tx_start,
    input  wire [7:0] tx_data,
    output reg        tx_serial,
    output reg        tx_busy
);

    function integer clog2;
        input integer value;
        integer i;
        begin
            value = value - 1;
            for (i = 0; value > 0; i = i + 1)
                value = value >> 1;
            clog2 = i;
        end
    endfunction

    localparam COUNT_WIDTH = (CLKS_PER_BIT > 1) ? clog2(CLKS_PER_BIT) : 1;

    reg [COUNT_WIDTH-1:0] clk_count;
    reg [3:0] bit_index;
    reg [7:0] tx_data_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            tx_serial <= 1'b1;
            tx_busy   <= 1'b0;
            clk_count <= {COUNT_WIDTH{1'b0}};
            bit_index <= 4'd0;
            tx_data_reg <= 8'd0;
        end else if (!tx_busy) begin
            if (tx_start) begin
                tx_serial <= 1'b0;
                tx_busy   <= 1'b1;
                clk_count <= {COUNT_WIDTH{1'b0}};
                bit_index <= 4'd0;
                tx_data_reg <= tx_data;
            end else begin
                tx_serial <= 1'b1;
                tx_busy   <= 1'b0;
            end
        end else if (clk_count == CLKS_PER_BIT - 1) begin
            clk_count <= {COUNT_WIDTH{1'b0}};
            if (bit_index == 4'd0) begin
                tx_serial <= tx_data_reg[0];
                bit_index <= 4'd1;
            end else if (bit_index < 4'd8) begin
                tx_serial <= tx_data_reg[bit_index];
                bit_index <= bit_index + 1'b1;
            end else if (bit_index == 4'd8) begin
                tx_serial <= 1'b1;
                bit_index <= 4'd9;
            end else begin
                tx_serial <= 1'b1;
                tx_busy   <= 1'b0;
                bit_index <= 4'd0;
            end
        end else begin
            clk_count <= clk_count + 1'b1;
        end
    end

endmodule

